import{_ as p,a0 as i,w as d,s as l,I as o,x as s,a1 as t,A as a,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Linux 下 SSH 命令實例指南 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 下 SSH 命令實例指南 | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 下 SSH 命令實例指南 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 下 SSH 命令實例指南 | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140819 A Pocket Guide for Linux ssh Command with Examples","title":"Linux 下 SSH 命令實例指南","tag":"201409","desc":""},"relativePath":"201409/20140819 A Pocket Guide for Linux ssh Command with Examples.md","filePath":"[post].md"}'),h={name:"201409/20140819 A Pocket Guide for Linux ssh Command with Examples.md"};function m(u,e,S,x,f,g){const n=i("Link");return d(),l("div",null,[e[19]||(e[19]=o("h1",{id:"linux-下-ssh-命令實例指南",tabindex:"-1"},[s("Linux 下 SSH 命令實例指南 "),o("a",{class:"header-anchor",href:"#linux-下-ssh-命令實例指南","aria-label":"Permalink to “Linux 下 SSH 命令實例指南”"},"​")],-1)),e[20]||(e[20]=o("p",null,"如果你已經在IT圈內混了很長時間, 應該對 SSH 這個了不起的工具及其安全特性有所耳聞吧. 本教程可以讓你在短時間內掌握通過 SSH 安全便利地連接到遠程計算機的技術.",-1)),o("p",null,[e[1]||(e[1]=s("如果你對 SSH 還沒什麼概念, 可以先訪問 ",-1)),t(n,{href:"http://en.wikipedia.org/wiki/Secure_Shell"},{default:a(()=>[...e[0]||(e[0]=[s("維基百科",-1)])]),_:1}),e[2]||(e[2]=s(" 進行了解.",-1))]),e[21]||(e[21]=r(`<h3 id="基本用法" tabindex="-1">基本用法 <a class="header-anchor" href="#基本用法" aria-label="Permalink to “基本用法”">​</a></h3><p>最簡單的 SSH 命令只需要指定用户名和主機名參數即可. 主機名可以是 IP 地址或者域名. 命令格式如下:</p><pre><code>$ ssh user@hostname
</code></pre><p>比如要在我的局域網內登錄一個樹莓派系統, 只需要簡單的在命令列輸入如下命令:</p><pre><code>$ ssh pi@10.42.0.47
</code></pre><p>命令中的 pi 和 10.42.0.47 分別是我的樹莓派系統的用户名和局域網 IP 地址. 實際使用時主機名需要改成你的目標主機(局域網內或者遠程)的 IP 地址.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/basic-ssh.png" alt="basic ssh"></p><p>如果你能夠成功登陸, 那麼下面的內容對你來説就輕而易舉了.</p><h3 id="使用其他端口" tabindex="-1">使用其他端口 <a class="header-anchor" href="#使用其他端口" aria-label="Permalink to “使用其他端口”">​</a></h3><p>SSH 默認連接到目標主機的 22 端口上,但是由於各種原因你可能需要連接到其他端口.</p><pre><code>$ ssh -p 10022 user@hostname
</code></pre><p>如上命令就是通過添加參數 -p 指定端口號為 10022.</p><h3 id="遠程執行命令" tabindex="-1">遠程執行命令 <a class="header-anchor" href="#遠程執行命令" aria-label="Permalink to “遠程執行命令”">​</a></h3><p>有時在遠程主機執行一條命令並顯示到本地, 然後繼續本地工作是很方便的. SSH 就能滿足這個需求:</p><pre><code>$ ssh pi@10.42.0.47 ls -l
</code></pre><p>比如上面這個命令就會枚舉遠程主機的主目錄內容並在本地顯示. 是不是很酷? 你可以嘗試下其他命令看看.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/remote-command.png" alt="remote command"></p><h3 id="掛載遠程文件系統" tabindex="-1">掛載遠程文件系統 <a class="header-anchor" href="#掛載遠程文件系統" aria-label="Permalink to “掛載遠程文件系統”">​</a></h3><p>另外一個很讚的基於 SSH 的工具叫 sshfs. sshfs 可以讓你在本地直接掛載遠程主機的文件系統.</p><pre><code>$ sshfs -o idmap=user user@hostname:/home/user ~/Remote
</code></pre><p>比如下面這條命令:</p><pre><code>$ sshfs -o idmap=user pi@10.42.0.47:/home/pi ~/Pi
</code></pre><p>該命令就將遠程主機 pi 用户的主目錄掛載到本地主目錄下的 Pi 文件夾.</p>`,23)),o("p",null,[e[4]||(e[4]=s("要詳細瞭解可以參考 ",-1)),t(n,{href:"http://linoxide.com/how-tos/sshfs-mount-remote-directories/"},{default:a(()=>[...e[3]||(e[3]=[s("sshfs 教程",-1)])]),_:1}),e[5]||(e[5]=s(".",-1))]),e[22]||(e[22]=r(`<h3 id="x11-圖形界面" tabindex="-1">X11 圖形界面 <a class="header-anchor" href="#x11-圖形界面" aria-label="Permalink to “X11 圖形界面”">​</a></h3><p>假如現在你想要在遠程主機運行一個圖形界面的程序, SSH 已經幫你想到了! 用前面提到的 SSH 基本命令加上參數 -X 連接到遠程主機即可開啓 X11 轉發功能. 登錄後你可能覺得沒什麼差別, 但是當你運行一個圖形界面程序後就會發現其中的不同的.</p><pre><code>$ ssh -X pi@10.42.0.47

$ pistore
</code></pre><p>如果你想在運行圖形界面程序的同時做些別的事情, 只需要簡單地在命令末尾加一個 &amp; 符號.</p><pre><code>$ pistore&amp;
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/X11-forwarding.png" alt="X11 forwarding"></p><h3 id="轉義字符" tabindex="-1">轉義字符 <a class="header-anchor" href="#轉義字符" aria-label="Permalink to “轉義字符”">​</a></h3><p>SSH 提供了多樣的轉義字符功能. 用 SSH 連接到任意一台遠程主機然後輸入 ~? 你就可以看到支持的轉義字符和功能説明列表. 以下例子展示了 <strong>~#</strong> 和 <strong>~C</strong> 的效果.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/escape-sequences.png" alt="escape sequences"></p><h3 id="配置-ssh" tabindex="-1">配置 SSH <a class="header-anchor" href="#配置-ssh" aria-label="Permalink to “配置 SSH”">​</a></h3><p>如果你需要改變 SSH 的配置, 請用你喜好的文本編輯器打開 <strong>/etc/ssh/sshd_config</strong> 進行編輯. 比如你想改變登陸的標語, 在配置文件中找到下面這行:</p><pre><code>#Banner none
</code></pre><p>刪除 # 字符(取消該行的註釋), 將 none 替換為包含你期望顯示內容的文件地址. 修改後該行應該類似這樣:</p><pre><code>Banner /etc/issue
</code></pre><p>在配置文件 <strong>/etc/ssh/sshd_config</strong> 中你還可以找到端口號, 空閒超時時間等配置項. 配置項大都比較容易理解, 但是保險起見在你修改一些不是很確定的配置項時最好參考下 SSH 的幫助文檔.</p><h3 id="構建-ssh-密鑰對" tabindex="-1">構建 ssh 密鑰對 <a class="header-anchor" href="#構建-ssh-密鑰對" aria-label="Permalink to “構建 ssh 密鑰對”">​</a></h3><p>運行以下命令創建密鑰對:</p><pre><code>$ ssh-keygen -t dsa
</code></pre><p>此命令會要求你輸入密碼(可以留空), 然後就會生成密鑰並會顯示一張該密鑰對應的隨機圖.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/generate-key-pair.png" alt="generate key pair"></p><h3 id="尋找主機密鑰" tabindex="-1">尋找主機密鑰 <a class="header-anchor" href="#尋找主機密鑰" aria-label="Permalink to “尋找主機密鑰”">​</a></h3><p>在你準備添加密鑰之前不妨先用以下命令看看是否已經添加了對應主機的密鑰了.</p><pre><code>$ ssh-keygen -F 10.42.0.47
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/find-hostkey.png" alt="find hostkey"></p><h3 id="刪除主機密鑰" tabindex="-1">刪除主機密鑰 <a class="header-anchor" href="#刪除主機密鑰" aria-label="Permalink to “刪除主機密鑰”">​</a></h3><p>某些情況下, 比如主機地址更改或者不再使用某個密鑰, 你就可能需要刪除某個密鑰.</p><pre><code>$ ssh-keygen -R 10.42.0.47
</code></pre><p>用以上命令就可刪除. 這比手動在 <strong>~/.ssh/known_hosts</strong> 文件中刪除要方便很多.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/remove-hostkey.png" alt="remove hostkey"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>通過以上的內容你應該可以輕鬆使用 SSH 了. SSH 還有很多功能值得你去發掘, 這就要看你的想像力了。</p><hr>`,32)),o("p",null,[e[7]||(e[7]=s("via: ",-1)),t(n,{href:"http://linoxide.com/linux-command/pocket-guide-linux-ssh-command/"},{default:a(()=>[...e[6]||(e[6]=[s("http://linoxide.com/linux-command/pocket-guide-linux-ssh-command/",-1)])]),_:1})]),o("p",null,[e[11]||(e[11]=s("作者：",-1)),t(n,{href:"http://linoxide.com/author/bobbin/"},{default:a(()=>[...e[8]||(e[8]=[s("Bobbin Zachariah",-1)])]),_:1}),e[12]||(e[12]=s(" 譯者：",-1)),t(n,{href:"https://github.com/henryfour"},{default:a(()=>[...e[9]||(e[9]=[s("henryfour",-1)])]),_:1}),e[13]||(e[13]=s(" 校對：",-1)),t(n,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...e[10]||(e[10]=[s("Caroline",-1)])]),_:1})]),o("p",null,[e[16]||(e[16]=s("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[14]||(e[14]=[s("LCTT",-1)])]),_:1}),e[17]||(e[17]=s(" 原創翻譯，",-1)),t(n,{href:"http://linux.cn/"},{default:a(()=>[...e[15]||(e[15]=[s("Linux中國",-1)])]),_:1}),e[18]||(e[18]=s(" 榮譽推出",-1))])])}const T=p(h,[["render",m]]);export{k as __pageData,T as default};
